pub fn entangleNodes(self: *Graph, a_id: []u8, b_id: []u8) !void {
    // 1. Check if already entangled
    if (entanglements.contains(pair(a, b))) 
        return error.AlreadyEntangled;

    // 2. Create entangled edges
    edge_ab.quality = .entangled;
    edge_ab.quantum_correlation = Complex(1.0, 0.0);

    edge_ba.quality = .entangled;
    edge_ba.quantum_correlation = Complex(1.0, 0.0);

    // 3. Store Bell state
    entanglements.put(pair(a, b), BellPhiPlus());
}


